#!/usr/bin/env bash
# SayurLogi — Google Auth fix (STANDALONE, no git needed)
# Self-contained: embeds both files as base64, writes directly.
# Works regardless of VPS git state (diverged, behind, etc).
#
# Files updated:
#   1. next.config.ts            → CSP allow accounts.google.com
#   2. src/components/grocery/google-signin-button.tsx → watchdog polling
#
# MD5: d357ac0c0cb686a8eb7378413ea21edc
set -euo pipefail

cd ~/sayurlogi 2>/dev/null || { echo "ERR: ~/sayurlogi tidak ditemukan"; exit 1; }
echo "==> Working directory: $(pwd)"

# Backup old files (timestamped)
TS=$(date +%Y%m%d-%H%M%S)
echo "==> Backup old files..."
cp next.config.ts "next.config.ts.bak.$TS"
cp src/components/grocery/google-signin-button.tsx "google-signin-button.tsx.bak.$TS"
echo "    Backed up to *.bak.$TS"

# Write new next.config.ts
echo "==> Update next.config.ts (CSP allow accounts.google.com)..."
echo "" | base64 -d > next.config.ts

# Write new GoogleSignInButton
echo "==> Update src/components/grocery/google-signin-button.tsx (watchdog polling)..."
echo "" | base64 -d > src/components/grocery/google-signin-button.tsx

# Verify
echo "==> Verify changes..."
grep -q "accounts.google.com" next.config.ts && echo "    ✓ next.config.ts: CSP updated" || { echo "    ✗ next.config.ts: FAILED"; exit 1; }
grep -q "waitForGisApi" src/components/grocery/google-signin-button.tsx && echo "    ✓ google-signin-button.tsx: watchdog added" || { echo "    ✗ google-signin-button.tsx: FAILED"; exit 1; }

echo "==> Build production (may take 1-2 min)..."
bun run build

echo "==> Restart PM2..."
pm2 restart sayurlogi

echo ""
echo "✅ Done. Verify in browser:"
echo "   1. Hard refresh (Ctrl+Shift+R) storefront"
echo "   2. Click 'Masuk akun' → Google button should appear in 2-3s"
echo "   3. If still loading >10s, check Google Cloud Console:"
echo "      Credentials → OAuth Client ID → Authorized JavaScript origins"
echo "      must include: http://100.110.249.2:3000"
echo ""
echo "Rollback (if needed):"
echo "   cp next.config.ts.bak.$TS next.config.ts"
echo "   cp google-signin-button.tsx.bak.$TS src/components/grocery/google-signin-button.tsx"
echo "   bun run build && pm2 restart sayurlogi"
